import{_ as r,o as a,c as e,ag as n}from"./chunks/framework.BJFNwp4n.js";const u=JSON.parse('{"title":"Module 5: Travel","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/modules/maltese-module5-analysis.md","filePath":"en/more/maltese/modules/maltese-module5-analysis.md"}'),o={name:"en/more/maltese/modules/maltese-module5-analysis.md"};function s(i,t,d,l,g,h){return a(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794416186000"},[...t[0]||(t[0]=[n('<h1 id="module-5-travel" tabindex="-1">Module 5: Travel <a class="header-anchor" href="#module-5-travel" aria-label="Permalink to &quot;Module 5: Travel&quot;">​</a></h1><p><strong>Is-safar — Travel</strong></p><h2 id="cover-page-breakdown" tabindex="-1">Cover Page Breakdown <a class="header-anchor" href="#cover-page-breakdown" aria-label="Permalink to &quot;Cover Page Breakdown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>MQF 2 – Maltese Language and Cultural Orientation for Foreigners</td><td>MQF Level 2: Maltese language and cultural orientation for foreigners.<br><strong>MQF 2</strong> a qualification level, not &quot;second module&quot;<br><strong>Maltese Language</strong> the Maltese language<br><strong>Cultural Orientation</strong> cultural orientation / introduction<br><strong>for Foreigners</strong> for foreigners.</td></tr><tr><td>Module 5 / Is-safar</td><td>Module 5: travel.<br><strong>Module 5</strong> module 5<br><strong>is-</strong> the definite article il- assimilated before s<br><strong>safar</strong> travel, travelling abroad (noun).</td></tr></tbody></table><hr><h2 id="_1-the-reading-passage-line-by-line" tabindex="-1">1 The Reading Passage, Line by Line <a class="header-anchor" href="#_1-the-reading-passage-line-by-line" aria-label="Permalink to &quot;1 The Reading Passage, Line by Line&quot;">​</a></h2><p><code>Il-Qari – Aqra din is-silta u wara wieġeb il-mistoqsijiet</code> Reading: read this passage and then answer the questions. <strong>Aqra</strong> read; <strong>din is-silta</strong> this passage; <strong>u wara</strong> and then; <strong>wieġeb</strong> answer; <strong>il-mistoqsijiet</strong> the questions.</p><table tabindex="0"><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>F&#39;April li għadda, jien u l-għarus tiegħi sifirna sal-Italja.</td><td>Last April my fiancé and I travelled to Italy.<br><strong>F&#39;April</strong> in April<br><strong>li għadda</strong> last, past (modifying April)<br><strong>jien</strong> I<br><strong>u</strong> and<br><strong>l-għarus tiegħi</strong> my boyfriend/fiancé<br><strong>sifirna</strong> we travelled (past tense)<br><strong>sal-Italja</strong> to Italy, sa + the definite article.</td></tr><tr><td>Malli wasalna l-ajruport ħadt qatgħa għax ħsibt li kelli l-bagalja itqal milli suppost!</td><td>As soon as we reached the airport I got a shock, because I thought my suitcase was heavier than allowed.<br><strong>Malli</strong> as soon as<br><strong>wasalna</strong> we arrived<br><strong>l-ajruport</strong> the airport; here &quot;to the airport&quot;<br><strong>ħadt qatgħa</strong> I got a shock (fixed expression)<br><strong>għax</strong> because<br><strong>ħsibt</strong> I thought<br><strong>li</strong> that<br><strong>kelli</strong> I had<br><strong>l-bagalja</strong> the suitcase<br><strong>itqal</strong> heavier<br><strong>milli suppost</strong> than it should be.</td></tr><tr><td>Iżda mbagħad ikkonfermajna li kollox kien sew.</td><td>But then we confirmed that everything was fine.<br><strong>Iżda</strong> but<br><strong>mbagħad</strong> then, afterwards<br><strong>ikkonfermajna</strong> we confirmed<br><strong>li</strong> that<br><strong>kollox</strong> everything<br><strong>kien</strong> was<br><strong>sew</strong> fine, in order.</td></tr><tr><td>Kif irfisna fuq l-art Taljana, mill-ewwel ħassejna lit-temp kien iktar frisk minn dak li konna ħallejna warajna Malta.</td><td>As soon as we set foot on Italian soil we felt at once that the weather was cooler than the Malta we had left behind. The textbook&#39;s <code>lit-temp</code> is better read as <code>li t-temp</code>.<br><strong>Kif</strong> when, as soon as<br><strong>irfisna</strong> we trod, set foot<br><strong>fuq</strong> on<br><strong>l-art Taljana</strong> Italian soil (Taljana is feminine with art)<br><strong>mill-ewwel</strong> at once<br><strong>ħassejna</strong> we felt<br><strong>li t-temp</strong> that the weather …<br><strong>kien iktar frisk</strong> was cooler<br><strong>minn dak</strong> than that, i.e. the earlier weather<br><strong>li konna ħallejna</strong> that we had left<br><strong>warajna</strong> behind us<br><strong>Malta</strong> in Malta.</td></tr><tr><td>Fl-ewwel ġurnata żorna Pisa, imbagħad Firenze kif ukoll Cinque Terre; xi ġmiel kien hemm!</td><td>On the first day we visited Pisa, then Florence and also Cinque Terre; how beautiful it was there!<br><strong>Fl-ewwel ġurnata</strong> on the first day<br><strong>żorna</strong> we visited<br><strong>Pisa / Firenze / Cinque Terre</strong> Pisa / Florence / Cinque Terre<br><strong>imbagħad</strong> then<br><strong>kif ukoll</strong> as well as<br><strong>xi ġmiel</strong> what beauty (exclamation)<br><strong>kien hemm</strong> there was.</td></tr><tr><td>L-iktar ħaġa li laqtitni kien il-Katidral ta&#39; Firenze daqskemm hu kbir!</td><td>The thing that struck me most was Florence Cathedral, it is so big!<br><strong>L-iktar ħaġa</strong> the most … thing<br><strong>li laqtitni</strong> that struck me, -ni = me<br><strong>kien</strong> was<br><strong>il-Katidral</strong> the cathedral<br><strong>ta&#39; Firenze</strong> of Florence<br><strong>daqskemm</strong> how much, so<br><strong>hu kbir</strong> it is big.</td></tr><tr><td>Minkejja dan, l-isbaħ veduti kienu ta&#39; Cinque Terre, għax hemm ħafna natura, ħdura u paċi.</td><td>Even so, the most beautiful views were those of Cinque Terre, because there is plenty of nature, greenery and peace.<br><strong>Minkejja dan</strong> in spite of this<br><strong>l-isbaħ veduti</strong> the most beautiful views<br><strong>kienu</strong> were (plural)<br><strong>ta&#39; Cinque Terre</strong> of Cinque Terre<br><strong>għax</strong> because<br><strong>hemm</strong> there is<br><strong>ħafna</strong> a lot<br><strong>natura</strong> nature<br><strong>ħdura</strong> greenery<br><strong>u paċi</strong> and peace.</td></tr><tr><td>Imxejna ħafna, speċjalment bejn raħal u ieħor u b&#39;hekk gawdejna l-inħawi aħjar.</td><td>We walked a lot, especially from one village to another, and so we enjoyed the surroundings better.<br><strong>Imxejna</strong> we walked<br><strong>ħafna</strong> a lot<br><strong>speċjalment</strong> especially<br><strong>bejn</strong> between<br><strong>raħal u ieħor</strong> one village and another<br><strong>u b&#39;hekk</strong> and thereby<br><strong>gawdejna</strong> we enjoyed<br><strong>l-inħawi</strong> the surroundings<br><strong>aħjar</strong> better, more fully.</td></tr><tr><td>L-ikel Taljan ukoll huwa mill-aqwa.</td><td>Italian food is excellent as well.<br><strong>L-ikel Taljan</strong> Italian food<br><strong>ukoll</strong> also<br><strong>huwa</strong> is<br><strong>mill-aqwa</strong> of the best, excellent (fixed expression).</td></tr><tr><td>L-itjeb ikla li ħadna kienet minn Firenze, li kienet tikkonsistni f&#39;taħlita ta&#39; ikel differenti; għaġin, laħam u ħut!</td><td>The best meal we had came from Florence, made up of a mixture of different foods: pasta, meat and fish. <code>tikkonsistni</code> is probably <code>tikkonsisti</code>.<br><strong>L-itjeb ikla</strong> the best meal<br><strong>li ħadna</strong> that we had; ħadna literally &quot;we took&quot;<br><strong>kienet</strong> was (feminine, with ikla)<br><strong>minn Firenze</strong> from Florence<br><strong>li kienet tikkonsisti</strong> which consisted of<br><strong>f&#39;taħlita</strong> in a mixture<br><strong>ta&#39; ikel differenti</strong> of different foods<br><strong>għaġin</strong> pasta<br><strong>laħam</strong> meat<br><strong>u ħut</strong> and fish.</td></tr><tr><td>Wara dan kollu, dejjem ħallejna spazju għall-ħelu speċjalment għall-kantucci jew għal xi ġelat!</td><td>After all that we always left room for something sweet, especially cantucci or an ice cream!<br><strong>Wara dan kollu</strong> after all this<br><strong>dejjem</strong> always<br><strong>ħallejna</strong> we left<br><strong>spazju</strong> space, here room in the stomach<br><strong>għall-ħelu</strong> for something sweet<br><strong>speċjalment</strong> especially<br><strong>għall-kantucci</strong> for cantucci, Italian almond biscuits<br><strong>jew</strong> or<br><strong>għal xi ġelat</strong> for some ice cream.</td></tr></tbody></table><h3 id="six-reading-questions" tabindex="-1">Six Reading Questions <a class="header-anchor" href="#six-reading-questions" aria-label="Permalink to &quot;Six Reading Questions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question and full reference answer</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Meta siefru? — Is-safra kienet f&#39;April li għadda.</td><td>When did they travel? — The trip was last April.<br><strong>Meta</strong> when<br><strong>siefru</strong> they travelled, as worded in the question<br><strong>Is-safra</strong> the trip<br><strong>kienet</strong> was<br><strong>f&#39;April</strong> in April<br><strong>li għadda</strong> last.</td></tr><tr><td>Fejn marru? — Marru l-Italja u żaru Pisa, Firenze u Cinque Terre.</td><td>Where did they go? — To Italy, visiting Pisa, Florence and Cinque Terre.<br><strong>Fejn</strong> where<br><strong>marru</strong> they went<br><strong>l-Italja</strong> Italy<br><strong>u żaru</strong> and visited<br><strong>Pisa, Firenze u Cinque Terre</strong> three place names.</td></tr><tr><td>X&#39;inhi l-iktar ħaġa li laqtitha u għaliex? — L-iktar li laqatha kien il-Katidral ta&#39; Firenze għax huwa kbir ħafna.</td><td>What struck her most, and why? — Florence Cathedral, because it is very big.<br><strong>X&#39;inhi</strong> what is it, x&#39; + hi<br><strong>l-iktar ħaġa</strong> the most … thing<br><strong>li laqtitha</strong> that struck her<br><strong>u għaliex</strong> and why<br><strong>L-iktar li laqatha</strong> what struck her most<br><strong>kien il-Katidral ta&#39; Firenze</strong> was Florence Cathedral<br><strong>għax huwa kbir ħafna</strong> because it is very big.</td></tr><tr><td>Fejn raw l-isbaħ veduti? — Raw l-isbaħ veduti f&#39;Cinque Terre, fejn hemm ħafna ħdura u paċi.</td><td>Where did they see the most beautiful views? — Cinque Terre, where there is plenty of greenery and peace.<br><strong>raw</strong> they saw<br><strong>l-isbaħ veduti</strong> the most beautiful views<br><strong>f&#39;Cinque Terre</strong> in Cinque Terre<br><strong>fejn</strong> where<br><strong>hemm ħafna ħdura u paċi</strong> there is plenty of greenery and peace.</td></tr><tr><td>Liema kienet l-itjeb ikla li ħadu? — L-itjeb ikla kienet f&#39;Firenze u kienet tinkludi għaġin, laħam u ħut.</td><td>Which was the best meal they had? — One in Florence, with pasta, meat and fish.<br><strong>Liema</strong> which<br><strong>kienet l-itjeb ikla</strong> was the best meal<br><strong>li ħadu</strong> that they had<br><strong>f&#39;Firenze</strong> in Florence<br><strong>u kienet tinkludi</strong> and it included<br><strong>għaġin, laħam u ħut</strong> pasta, meat and fish.</td></tr><tr><td>Semmi 2 tipi ta&#39; ħelu li hemm fis-silta. — Fis-silta jissemmew il-kantucci u l-ġelat.</td><td>Name two kinds of sweet food in the passage. — Cantucci and ice cream.<br><strong>Semmi</strong> list, name<br><strong>żewġ tipi ta&#39; ħelu</strong> two kinds of sweet food<br><strong>li hemm fis-silta</strong> that are in the passage<br><strong>jissemmew</strong> are mentioned<br><strong>il-kantucci u l-ġelat</strong> the cantucci and the ice cream.</td></tr></tbody></table><hr><h2 id="_2-gender-and-comparison-of-adjectives" tabindex="-1">2 Gender and Comparison of Adjectives <a class="header-anchor" href="#_2-gender-and-comparison-of-adjectives" aria-label="Permalink to &quot;2 Gender and Comparison of Adjectives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Original sentence or example</th><th>Translation and notes</th></tr></thead><tbody><tr><td>L-aġġettiv jiddeskrivi n-nom u dan ukoll għandu ġens.</td><td>The adjective describes the noun, and the noun also has a gender.<br><strong>L-aġġettiv</strong> the adjective<br><strong>jiddeskrivi</strong> describes<br><strong>n-nom</strong> the noun<br><strong>u dan ukoll</strong> and this too<br><strong>għandu</strong> has<br><strong>ġens</strong> grammatical gender.</td></tr><tr><td>L-aġġettiv irid jaqbel mal-ġens tan-nom ukoll.</td><td>The adjective must agree with the gender of the noun as well.<br><strong>irid</strong> must<br><strong>jaqbel</strong> agree<br><strong>mal-ġens</strong> with the gender, ma&#39; + the definite article<br><strong>tan-nom</strong> of the noun<br><strong>ukoll</strong> too.</td></tr><tr><td>Tifel kbir – tifla kbira</td><td>A big boy – a big girl.<br><strong>tifel / tifla</strong> boy / girl<br><strong>kbir / kbira</strong> big, masculine / feminine.</td></tr><tr><td>Raġel xiħ – mara xiħa</td><td>An old man – an old woman.<br><strong>raġel / mara</strong> man / woman<br><strong>xiħ / xiħa</strong> old, masculine / feminine.</td></tr><tr><td>Kowt iswed – beritta sewda</td><td>A black coat – a black cap.<br><strong>kowt / beritta</strong> coat / cap<br><strong>iswed / sewda</strong> black, masculine / feminine; the feminine does not simply add a.</td></tr><tr><td>Meta tqabbel ħaġa ma&#39; oħra tuża l-komparattiv.</td><td>When you compare one thing with another you use the comparative.<br><strong>Meta</strong> when<br><strong>tqabbel</strong> you compare<br><strong>ħaġa</strong> thing<br><strong>ma&#39; oħra</strong> with another<br><strong>tuża</strong> you use<br><strong>l-komparattiv</strong> the comparative.</td></tr><tr><td>Meta tqabbel iktar minn żewġ oġġetti flimkien, tuża s-superlattiv.</td><td>The textbook says: when comparing more than two objects together, use the superlative. What actually matters is expressing &quot;the most …&quot; within a range, not mechanically counting objects.<br><strong>iktar minn</strong> more than<br><strong>żewġ oġġetti</strong> two objects<br><strong>flimkien</strong> together<br><strong>s-superlattiv</strong> the superlative.</td></tr></tbody></table><p>Picture note: <strong>kbir → ikbar → l-ikbar</strong> = big → bigger → biggest. The comparative often goes with <strong>minn</strong> (than), and the superlative is usually defined by <strong>fil-klassi / minn kulħadd</strong> (in the class / of everybody). The textbook&#39;s <strong>P.eż.</strong> = pereżempju, &quot;for example&quot;.</p><h3 id="the-gap-fill-table" tabindex="-1">The Gap-Fill Table <a class="header-anchor" href="#the-gap-fill-table" aria-label="Permalink to &quot;The Gap-Fill Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Masculine</th><th>Feminine</th><th>Comparative</th><th>Superlative</th><th>Meaning</th></tr></thead><tbody><tr><td>tqil</td><td>tqila</td><td>itqal</td><td>l-itqal</td><td>heavy / heavier / heaviest</td></tr><tr><td>frisk</td><td>friska</td><td>iktar frisk / friska</td><td>l-iktar frisk / friska</td><td>cool / fresher; choose the gender of the noun it modifies</td></tr><tr><td>ħafna</td><td>not applicable</td><td>iktar</td><td>l-iktar</td><td>much / more / most; a special quantifier row</td></tr><tr><td>kbir</td><td>kbira</td><td>ikbar</td><td>l-ikbar</td><td>big / bigger / biggest</td></tr><tr><td>sabiħ</td><td>sabiħa</td><td>isbaħ</td><td>l-isbaħ</td><td>beautiful / more beautiful / most beautiful</td></tr><tr><td>qawwi</td><td>qawwija</td><td>aqwa</td><td>l-aqwa</td><td>strong / stronger / strongest; also &quot;excellent&quot;</td></tr><tr><td>tajjeb</td><td>tajba</td><td>itjeb</td><td>l-itjeb</td><td>good / better / best</td></tr></tbody></table><p><code>iktar frisk</code> is the analytic comparative given by the exercise itself; do not swap it for another word just to satisfy a rule. The <code>l-</code> in the superlative is the form of the definite article.</p><hr><h2 id="_3-adjective-stems-the-complete-table" tabindex="-1">3 Adjective Stems: The Complete Table <a class="header-anchor" href="#_3-adjective-stems-the-complete-table" aria-label="Permalink to &quot;3 Adjective Stems: The Complete Table&quot;">​</a></h2><p>Each row reads left to right as &quot;masculine base form, feminine base form, comparative, superlative&quot;. The last column gives the meaning; the comparative reads &quot;more …&quot;, the superlative &quot;most …&quot;.</p><table tabindex="0"><thead><tr><th>Masculine</th><th>Feminine</th><th>Comparative</th><th>Superlative</th><th>Meaning and use</th></tr></thead><tbody><tr><td>sabiħ</td><td>sabiħa</td><td>isbaħ</td><td>l-isbaħ</td><td>beautiful; sabiħa with a feminine noun</td></tr><tr><td>ikrah</td><td>kerha</td><td>ikreh</td><td>l-ikreh</td><td>ugly; the feminine stem changes noticeably</td></tr><tr><td>tajjeb</td><td>tajba</td><td>itjeb</td><td>l-itjeb</td><td>good, tasty; echoes the food on page 1</td></tr><tr><td>ħażin</td><td>ħażina</td><td>eħżen</td><td>l-eħżen</td><td>bad, poor</td></tr><tr><td>għoli</td><td>għolja</td><td>ogħla</td><td>l-ogħla</td><td>high; also expensive</td></tr><tr><td>irħis</td><td>irħisa</td><td>irħas</td><td>l-irħas</td><td>cheap</td></tr><tr><td>oħxon</td><td>ħoxna</td><td>eħxen</td><td>l-eħxen</td><td>thick, coarse, fat; depending on context</td></tr><tr><td>irqiq</td><td>rqiqa</td><td>irqaq</td><td>l-irqaq</td><td>thin, fine, slim</td></tr><tr><td>kbir</td><td>kbira</td><td>ikbar</td><td>l-ikbar</td><td>big; also older</td></tr><tr><td>żgħir</td><td>żgħira</td><td>iżgħar</td><td>l-iżgħar</td><td>small, young</td></tr><tr><td>ċkejken</td><td>ċkejkna</td><td>iċken</td><td>l-iċken</td><td>tiny, very small</td></tr><tr><td>tqil</td><td>tqila</td><td>itqal</td><td>l-itqal</td><td>heavy; also difficult</td></tr><tr><td>ħafif</td><td>ħafifa</td><td>eħfef</td><td>l-eħfef</td><td>light, easy</td></tr><tr><td>dejjaq</td><td>dejqa</td><td>idjaq</td><td>l-idjaq</td><td>narrow</td></tr><tr><td>wiesa&#39;</td><td>wiesgħa</td><td>usa&#39;</td><td>l-usa&#39;</td><td>wide, spacious; the final apostrophe is kept</td></tr><tr><td>qawwi</td><td>qawwija</td><td>aqwa</td><td>l-aqwa</td><td>strong, powerful, excellent</td></tr><tr><td>għażiż</td><td>għażiża</td><td>egħżeż</td><td>l-egħżeż</td><td>dear, precious</td></tr><tr><td>twil</td><td>twila</td><td>itwal</td><td>l-itwal</td><td>long, tall; of a person, height</td></tr><tr><td>qasir</td><td>qasira</td><td>iqsar</td><td>l-iqsar</td><td>short, low</td></tr><tr><td>fqir</td><td>fqira</td><td>ifqar</td><td>l-ifqar</td><td>poor</td></tr><tr><td>xiħ</td><td>xiħa</td><td>ixjeħ</td><td>l-ixjeħ</td><td>old, usually of living beings</td></tr><tr><td>qadim</td><td>qadima</td><td>eqdem</td><td>l-eqdem</td><td>old, ancient, usually of things</td></tr><tr><td>ġdid</td><td>ġdida</td><td>iġded</td><td>l-iġded</td><td>new</td></tr></tbody></table><h3 id="analytic-comparison" tabindex="-1">Analytic Comparison <a class="header-anchor" href="#analytic-comparison" aria-label="Permalink to &quot;Analytic Comparison&quot;">​</a></h3><p><code>Il-komparattiv u s-superlattiv mhux dejjem jinħadmu b&#39;dan il-mod. Xi aġġettivi jeħtieġu ż-żieda tal-kelma…</code></p><p>Translation: the comparative and the superlative are not always formed this way; some adjectives need an extra word.</p><p><strong>Il-komparattiv u s-superlattiv</strong> the comparative and the superlative.<br><strong>mhux dejjem</strong> not always.<br><strong>jinħadmu</strong> are formed.<br><strong>b&#39;dan il-mod</strong> in this way.<br><strong>Xi aġġettivi</strong> some adjectives.<br><strong>jeħtieġu</strong> need.<br><strong>ż-żieda</strong> the addition.<br><strong>tal-kelma</strong> of a word.</p><table tabindex="0"><thead><tr><th>Masculine</th><th>Feminine</th><th>Comparative (suggested fill-in)</th><th>Superlative (suggested fill-in)</th><th>Meaning</th></tr></thead><tbody><tr><td>bravu</td><td>brava</td><td>iktar bravu / brava</td><td>l-iktar bravu / brava</td><td>capable, good at something</td></tr><tr><td>intelliġenti</td><td>intelliġenti</td><td>iktar intelliġenti</td><td>l-iktar intelliġenti</td><td>intelligent; same form for both genders</td></tr><tr><td>stupidu</td><td>stupida</td><td>iktar stupidu / stupida</td><td>l-iktar stupidu / stupida</td><td>stupid; applying it to a person can be offensive</td></tr><tr><td>modern</td><td>moderna</td><td>iktar modern / moderna</td><td>l-iktar modern / moderna</td><td>modern</td></tr><tr><td>sinjur</td><td>sinjura</td><td>iktar sinjur / sinjura</td><td>l-iktar sinjur / sinjura</td><td>rich; here not the title &quot;Mr / Madam&quot;</td></tr><tr><td>abjad</td><td>bajda</td><td>iktar abjad / bajda</td><td>l-iktar abjad / bajda</td><td>white</td></tr><tr><td>ċar</td><td>ċara</td><td>iktar ċar / ċara</td><td>l-iktar ċar / ċara</td><td>clear, light in colour</td></tr><tr><td>skur</td><td>skura</td><td>iktar skur / skura</td><td>l-iktar skur / skura</td><td>dark, dim</td></tr></tbody></table><p><strong>iktar / iżjed</strong> both mean &quot;more&quot;; <strong>l-iktar / l-iżjed</strong> both mean &quot;most&quot;. Here the textbook&#39;s analytic exercise is followed; it does not mean these words exclude other comparative expressions in every context.</p><hr><h2 id="_4-fifteen-complete-gap-fill-answers" tabindex="-1">4 Fifteen Complete Gap-Fill Answers <a class="header-anchor" href="#_4-fifteen-complete-gap-fill-answers" aria-label="Permalink to &quot;4 Fifteen Complete Gap-Fill Answers&quot;">​</a></h2><p>Exercise <code>Imla l-vojt bil-komparattiv jew bis-superlattiv, skont l-aġġettiv li hemm fil-parentesi</code>: fill the gap with the comparative or the superlative, according to the adjective in brackets. <strong>Imla</strong> fill; <strong>il-vojt</strong> the gap; <strong>bil-</strong> with the; <strong>jew</strong> or; <strong>skont</strong> according to; <strong>fil-parentesi</strong> in brackets.</p><table tabindex="0"><thead><tr><th>Completed sentence</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>1. Id-dar tiegħi hija <strong>ikbar</strong> minn tiegħek, imma ta&#39; ommi hija <strong>l-ikbar</strong> minn tagħna kollha.</td><td>My house is bigger than yours, but my mother&#39;s is the biggest of all of ours.<br><strong>Id-dar tiegħi</strong> my house<br><strong>hija ikbar</strong> is bigger<br><strong>minn tiegħek</strong> than yours<br><strong>imma</strong> but<br><strong>ta&#39; ommi</strong> my mother&#39;s, with dar left out<br><strong>hija l-ikbar</strong> is the biggest<br><strong>minn tagħna kollha</strong> among all of ours.</td></tr><tr><td>2. Daż-żarbun huwa <strong>l-eqdem</strong> wieħed.</td><td>This pair of shoes is the oldest one.<br><strong>Daż-żarbun</strong> this shoe / pair of shoes; da- combined with the definite article, not &quot;day&quot;<br><strong>huwa</strong> is<br><strong>l-eqdem</strong> the oldest<br><strong>wieħed</strong> one, referring to the item.</td></tr><tr><td>3. Il-Ġappun huwa <strong>l-isbaħ</strong> pajjiż li qatt mort.</td><td>Japan is the most beautiful country I have ever been to.<br><strong>Il-Ġappun</strong> Japan<br><strong>huwa l-isbaħ pajjiż</strong> is the most beautiful country<br><strong>li qatt mort</strong> that I ever went to; a fuller form adds fih.</td></tr><tr><td>4. Bl-ajruplan tasal <strong>iktar malajr</strong> milli bil-vapur.</td><td>By plane you arrive faster than by ship.<br><strong>Bl-ajruplan</strong> by plane<br><strong>tasal</strong> you arrive<br><strong>iktar malajr</strong> faster; also iżjed malajr<br><strong>milli</strong> than<br><strong>bil-vapur</strong> by ship.</td></tr><tr><td>5. Mill-istudenti tal-klassi, jien <strong>l-iżgħar</strong> waħda.</td><td>Among the students in the class, I am the youngest (female).<br><strong>Mill-istudenti</strong> among the students<br><strong>tal-klassi</strong> of the class<br><strong>jien</strong> I<br><strong>l-iżgħar</strong> the youngest<br><strong>waħda</strong> the feminine &quot;one&quot;, showing the speaker is female.</td></tr><tr><td>6. Dan il-kowt huwa <strong>eħxen</strong> mill-ieħor.</td><td>This coat is thicker than the other one.<br><strong>Dan il-kowt</strong> this coat<br><strong>huwa eħxen</strong> is thicker<br><strong>mill-ieħor</strong> than the other.</td></tr><tr><td>7. Slovenja hija pajjiż <strong>iktar frisk</strong> minn Malta.</td><td>Slovenia is a cooler country than Malta.<br><strong>Slovenja</strong> Slovenia<br><strong>hija pajjiż</strong> is a country<br><strong>iktar frisk</strong> cooler, masculine with pajjiż<br><strong>minn Malta</strong> than Malta.</td></tr><tr><td>8. L-Underground hija <strong>iktar effiċjenti</strong> mit-trasport pubbliku ta&#39; fuq l-art.</td><td>The Underground is more efficient than public transport above ground.<br><strong>L-Underground</strong> the underground railway<br><strong>hija</strong> is<br><strong>iktar effiċjenti</strong> more efficient<br><strong>mit-trasport pubbliku</strong> than public transport<br><strong>ta&#39; fuq l-art</strong> above ground.</td></tr><tr><td>9. Dan l-ikel huwa <strong>itjeb</strong> minn tal-bieraħ.</td><td>This food is better than yesterday&#39;s.<br><strong>Dan l-ikel</strong> this food<br><strong>huwa itjeb</strong> is better<br><strong>minn tal-bieraħ</strong> than yesterday&#39;s, with ikel left out.</td></tr><tr><td>10. Xagħar iz-zija huwa <strong>iqsar</strong> minn tiegħi.</td><td>My aunt&#39;s hair is shorter than mine.<br><strong>Xagħar</strong> hair<br><strong>iz-zija</strong> the aunt<br><strong>huwa iqsar</strong> is shorter<br><strong>minn tiegħi</strong> than mine.</td></tr><tr><td>11. It-triq tagħna hija <strong>l-idjaq</strong> fir-raħal kollu.</td><td>Our street is the narrowest in the whole village.<br><strong>It-triq tagħna</strong> our street<br><strong>hija l-idjaq</strong> is the narrowest<br><strong>fir-raħal kollu</strong> in the whole village.</td></tr><tr><td>12. <strong>L-ixjeħ</strong> persuna fid-dinja għandha mija u għoxrin sena!</td><td>The oldest person in the world is 120 years old! Only grammar practice from the original exercise, not a current fact.<br><strong>L-ixjeħ persuna</strong> the oldest person<br><strong>fid-dinja</strong> in the world<br><strong>għandha</strong> she / this person has; age is expressed with &quot;have&quot;<br><strong>mija u għoxrin sena</strong> one hundred and twenty years.</td></tr><tr><td>13. Ġorr dan il-basket għax <strong>eħfef</strong> mill-ieħor.</td><td>Carry this bag, because it is lighter than the other one.<br><strong>Ġorr</strong> carry, imperative<br><strong>dan il-basket</strong> this bag<br><strong>għax</strong> because<br><strong>eħfef</strong> lighter<br><strong>mill-ieħor</strong> than the other.</td></tr><tr><td>14. Dan l-eżami kien <strong>itqal</strong> minn ta&#39; qablu.</td><td>This exam was harder than the previous one.<br><strong>Dan l-eżami</strong> this exam<br><strong>kien</strong> was<br><strong>itqal</strong> heavier, here harder<br><strong>minn ta&#39; qablu</strong> than the one before it.</td></tr><tr><td>15. Il-vjaġġ lejn l-Ingilterra huwa <strong>itwal</strong> minn dak ta&#39; lejn l-Italja.</td><td>The journey to England is longer than the one to Italy.<br><strong>Il-vjaġġ</strong> the journey<br><strong>lejn l-Ingilterra</strong> to England<br><strong>huwa itwal</strong> is longer<br><strong>minn dak</strong> than that one<br><strong>ta&#39; lejn l-Italja</strong> of the journey to Italy.</td></tr></tbody></table><hr><h2 id="_5-the-past-tense-seventeen-complete-sentences" tabindex="-1">5 The Past Tense: Seventeen Complete Sentences <a class="header-anchor" href="#_5-the-past-tense-seventeen-complete-sentences" aria-label="Permalink to &quot;5 The Past Tense: Seventeen Complete Sentences&quot;">​</a></h2><p><code>Il-Verbi fil-Passat</code> the verbs in the past tense. <strong>Semitiċi</strong> of Semitic origin; <strong>li ġejjin mill-Għarbi</strong> coming from Arabic. The exercise <strong>Ikteb sentenza b&#39;dawn il-verbi</strong> = write one sentence with each of these verbs; <strong>Ikteb</strong> write; <strong>sentenza</strong> sentence; <strong>b&#39;dawn</strong> with these.</p><p>The form given at the head of each item is the third person masculine singular past, &quot;he …ed&quot;, not an infinitive or an imperative. The model sentences keep that form.</p><table tabindex="0"><thead><tr><th>Verb and model sentence</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>1. <strong>Kiteb</strong> — Ilbieraħ Mark kiteb ittra twila lil ħabibu biex jirrakkontalu dwar il-vaganza tiegħu.</td><td>Yesterday Mark wrote a long letter to his friend to tell him about his holiday.<br><strong>Ilbieraħ</strong> yesterday<br><strong>Mark</strong> a name<br><strong>kiteb</strong> he wrote<br><strong>ittra twila</strong> a long letter, feminine<br><strong>lil ħabibu</strong> to his friend, -u = his<br><strong>biex</strong> in order to<br><strong>jirrakkontalu</strong> tell him<br><strong>dwar</strong> about<br><strong>il-vaganza tiegħu</strong> his holiday.</td></tr><tr><td>2. <strong>Ħareġ</strong> — Wara x-xogħol, Paul ħareġ ma&#39; sħabu u marru jieklu f&#39;restorant qrib il-baħar.</td><td>After work Paul went out with his friends and they went to eat at a restaurant near the sea.<br><strong>Wara x-xogħol</strong> after work<br><strong>Paul ħareġ</strong> Paul went out<br><strong>ma&#39; sħabu</strong> with his friends<br><strong>u marru</strong> and they went<br><strong>jieklu</strong> to eat<br><strong>f&#39;restorant</strong> in a restaurant<br><strong>qrib il-baħar</strong> near the sea.</td></tr><tr><td>3. <strong>Fetaħ</strong> — Filgħodu missieri fetaħ it-twieqi tal-kċina għax il-kamra kienet sħuna ħafna.</td><td>In the morning my father opened the kitchen windows because the room was very hot.<br><strong>Filgħodu</strong> in the morning<br><strong>missieri</strong> my father<br><strong>fetaħ</strong> he opened<br><strong>it-twieqi</strong> the windows, plural<br><strong>tal-kċina</strong> of the kitchen<br><strong>għax</strong> because<br><strong>il-kamra</strong> the room<br><strong>kienet sħuna ħafna</strong> it was very hot.</td></tr><tr><td>4. <strong>Raqad</strong> — It-tifel raqad kmieni għax l-għada kellu jmur l-iskola u jagħmel eżami importanti.</td><td>The boy went to sleep early because the next day he had to go to school and sit an important exam.<br><strong>It-tifel</strong> the boy<br><strong>raqad kmieni</strong> he slept early<br><strong>għax</strong> because<br><strong>l-għada</strong> the next day<br><strong>kellu</strong> he had to<br><strong>jmur l-iskola</strong> go to school<br><strong>u jagħmel</strong> and do / sit<br><strong>eżami importanti</strong> an important exam.</td></tr><tr><td>5. <strong>Rikeb</strong> — It-turist rikeb il-ferrovija minn Ruma għal Firenze u gawda l-veduta mit-tieqa.</td><td>The tourist took the train from Rome to Florence and enjoyed the view from the window.<br><strong>It-turist</strong> the tourist<br><strong>rikeb</strong> he rode, took<br><strong>il-ferrovija</strong> the train<br><strong>minn Ruma għal Firenze</strong> from Rome to Florence<br><strong>u gawda</strong> and he enjoyed<br><strong>l-veduta</strong> the view<br><strong>mit-tieqa</strong> from the window.</td></tr><tr><td>6. <strong>Ħasel</strong> — Wara l-ikla, ħija ħasel il-platti u naddaf il-mejda biex jgħin lil ommi.</td><td>After the meal my brother washed the dishes and cleaned the table to help my mother.<br><strong>Wara l-ikla</strong> after the meal<br><strong>ħija</strong> my brother<br><strong>ħasel</strong> he washed<br><strong>il-platti</strong> the dishes<br><strong>u naddaf</strong> and cleaned<br><strong>il-mejda</strong> the table<br><strong>biex jgħin</strong> in order to help<br><strong>lil ommi</strong> my mother.</td></tr><tr><td>7. <strong>Għalaq</strong> — Is-sid għalaq il-ħanut fis-sebgħa ta&#39; filgħaxija u mar lura d-dar bil-karozza.</td><td>The owner closed the shop at seven in the evening and drove home.<br><strong>Is-sid</strong> the owner<br><strong>għalaq</strong> he closed<br><strong>il-ħanut</strong> the shop<br><strong>fis-sebgħa</strong> at seven<br><strong>ta&#39; filgħaxija</strong> of the evening<br><strong>u mar lura d-dar</strong> and he went back home<br><strong>bil-karozza</strong> by car.</td></tr><tr><td>8. <strong>Għamel</strong> — Nhar is-Sibt, David għamel kejk taċ-ċikkulata għal għeluq snin oħtu u żejnu bil-frott.</td><td>On Saturday David made a chocolate cake for his sister&#39;s birthday and decorated it with fruit.<br><strong>Nhar is-Sibt</strong> on Saturday<br><strong>David għamel</strong> David made<br><strong>kejk taċ-ċikkulata</strong> a chocolate cake<br><strong>għal għeluq snin</strong> for the birthday<br><strong>oħtu</strong> his sister<br><strong>u żejnu</strong> and he decorated it, -u = the cake<br><strong>bil-frott</strong> with fruit.</td></tr><tr><td>9. <strong>Tela&#39;</strong> — Il-viżitatur tela&#39; fuq it-torri biex jieħu ritratti tal-belt u tal-port minn fuq.</td><td>The visitor went up the tower to take pictures of the town and the harbour from above.<br><strong>Il-viżitatur</strong> the visitor<br><strong>tela&#39;</strong> he went up, apostrophe kept<br><strong>fuq it-torri</strong> up the tower<br><strong>biex jieħu ritratti</strong> to take pictures<br><strong>tal-belt u tal-port</strong> of the town and the harbour<br><strong>minn fuq</strong> from above.</td></tr><tr><td>10. <strong>Mela</strong> — Qabel il-vjaġġ, Mario mela l-flixkun bl-ilma u poġġieh fil-basket ħdejn l-ikel.</td><td>Before the trip Mario filled the bottle with water and put it in the bag next to the food.<br><strong>Qabel il-vjaġġ</strong> before the trip<br><strong>Mario mela</strong> Mario filled<br><strong>l-flixkun</strong> the bottle<br><strong>bl-ilma</strong> with water<br><strong>u poġġieh</strong> and he put it<br><strong>fil-basket</strong> in the bag<br><strong>ħdejn l-ikel</strong> next to the food<br><strong>mela</strong> here a verb, not the spoken filler &quot;then&quot;.</td></tr><tr><td>11. <strong>Wera</strong> — L-għalliem wera lill-istudenti mappa ta&#39; Malta u spjega fejn jinsabu l-bliet ewlenin.</td><td>The teacher showed the students a map of Malta and explained where the main towns are.<br><strong>L-għalliem</strong> the (male) teacher<br><strong>wera</strong> he showed<br><strong>lill-istudenti</strong> to the students<br><strong>mappa ta&#39; Malta</strong> a map of Malta<br><strong>u spjega</strong> and he explained<br><strong>fejn jinsabu</strong> where they are located<br><strong>l-bliet ewlenin</strong> the main towns.</td></tr><tr><td>12. <strong>Saq</strong> — Missieri saq bil-mod lejn l-ajruport għax kienet ix-xita u kien hemm ħafna traffiku.</td><td>My father drove slowly to the airport because it was raining and there was a lot of traffic.<br><strong>Missieri</strong> my father<br><strong>saq</strong> he drove<br><strong>bil-mod</strong> slowly<br><strong>lejn l-ajruport</strong> towards the airport<br><strong>għax</strong> because<br><strong>kienet ix-xita</strong> it was raining<br><strong>u kien hemm</strong> and there was<br><strong>ħafna traffiku</strong> a lot of traffic.</td></tr><tr><td>13. <strong>Dar</strong> — Il-gwida dar mal-belt mal-grupp u wriehom il-knejjes, il-pjazez u l-bini antik.</td><td>The guide took the group round the town and showed them the churches, squares and old buildings.<br><strong>Il-gwida</strong> the guide, male in this example<br><strong>dar</strong> he went round; not the noun &quot;house&quot;<br><strong>mal-belt</strong> round the town<br><strong>mal-grupp</strong> with the group<br><strong>u wriehom</strong> and he showed them<br><strong>il-knejjes</strong> the churches<br><strong>il-pjazez</strong> the squares<br><strong>u l-bini antik</strong> and the old buildings.</td></tr><tr><td>14. <strong>Mar</strong> — Il-Ħadd, Peter mar għand in-nanna u ħa miegħu ftit frott u kejk magħmul id-dar.</td><td>On Sunday Peter went to his grandmother and took some fruit and a homemade cake with him.<br><strong>Il-Ħadd</strong> Sunday<br><strong>Peter mar</strong> Peter went<br><strong>għand in-nanna</strong> to grandmother&#39;s place<br><strong>u ħa miegħu</strong> and he took with him<br><strong>ftit frott</strong> some fruit<br><strong>u kejk</strong> and a cake<br><strong>magħmul id-dar</strong> made at home.</td></tr><tr><td>15. <strong>Għam</strong> — Fis-sajf li għadda, Tom għam fil-baħar għal nofs siegħa qabel ma kiel ma&#39; sħabu.</td><td>Last summer Tom swam in the sea for half an hour before eating with his friends.<br><strong>Fis-sajf li għadda</strong> last summer<br><strong>Tom għam</strong> Tom swam<br><strong>fil-baħar</strong> in the sea<br><strong>għal nofs siegħa</strong> for half an hour<br><strong>qabel ma</strong> before<br><strong>kiel</strong> he ate<br><strong>ma&#39; sħabu</strong> with his friends.</td></tr><tr><td>16. <strong>Qam</strong> — Albert qam fis-sitta ta&#39; filgħodu biex jilħaq il-karozza tal-linja u jasal fil-ħin għax-xogħol.</td><td>Albert got up at six in the morning to catch the bus and get to work on time.<br><strong>Albert qam</strong> Albert got up<br><strong>fis-sitta ta&#39; filgħodu</strong> at six in the morning<br><strong>biex jilħaq</strong> to catch<br><strong>il-karozza tal-linja</strong> the bus<br><strong>u jasal</strong> and arrive<br><strong>fil-ħin</strong> on time<br><strong>għax-xogħol</strong> for work.</td></tr><tr><td>17. <strong>Kiel</strong> — Wara mixja twila, Daniel kiel platt għaġin bil-ħaxix u xorob tazza ilma fir-restorant.</td><td>After a long walk Daniel ate a plate of pasta with vegetables and drank a glass of water in the restaurant.<br><strong>Wara mixja twila</strong> after a long walk<br><strong>Daniel kiel</strong> Daniel ate<br><strong>platt għaġin</strong> a plate of pasta<br><strong>bil-ħaxix</strong> with vegetables<br><strong>u xorob</strong> and he drank<br><strong>tazza ilma</strong> a glass of water<br><strong>fir-restorant</strong> in the restaurant.</td></tr></tbody></table><hr><h2 id="_6-eighteen-more-past-tense-examples" tabindex="-1">6 Eighteen More Past-Tense Examples <a class="header-anchor" href="#_6-eighteen-more-past-tense-examples" aria-label="Permalink to &quot;6 Eighteen More Past-Tense Examples&quot;">​</a></h2><p><code>Mhux Semitiċi – li ġejjin mir-Rumanz u mill-Ingliż</code> not Semitic — coming from Romance and from English. <strong>mhux</strong> not; <strong>li ġejjin</strong> coming from; <strong>mir-Rumanz</strong> from Romance; <strong>mill-Ingliż</strong> from English. This is the textbook&#39;s grouping and is not used here to make strict etymological claims about each word.</p><table tabindex="0"><thead><tr><th>Verb and model sentence</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>1. <strong>Aċċetta</strong> — John aċċetta l-istedina ta&#39; ħabibu u mar għall-festa flimkien ma&#39; martu s-Sibt filgħaxija.</td><td>John accepted his friend&#39;s invitation and went to the party with his wife on Saturday evening.<br><strong>John aċċetta</strong> John accepted<br><strong>l-istedina</strong> the invitation<br><strong>ta&#39; ħabibu</strong> of his friend<br><strong>u mar għall-festa</strong> and he went to the party<br><strong>flimkien ma&#39; martu</strong> together with his wife<br><strong>s-Sibt filgħaxija</strong> Saturday evening.</td></tr><tr><td>2. <strong>Eduka</strong> — L-għalliem eduka lit-tfal dwar l-ambjent u għallimhom kif inaqqsu l-iskart fl-iskola.</td><td>The teacher educated the children about the environment and taught them how to reduce waste at school.<br><strong>L-għalliem</strong> the teacher<br><strong>eduka</strong> he educated<br><strong>lit-tfal</strong> the children<br><strong>dwar l-ambjent</strong> about the environment<br><strong>u għallimhom</strong> and he taught them<br><strong>kif inaqqsu</strong> how to reduce<br><strong>l-iskart</strong> waste<br><strong>fl-iskola</strong> at school.</td></tr><tr><td>3. <strong>Falla</strong> — L-istudent falla l-eżami tal-Malti, iżda ddeċieda li jistudja aktar u jerġa&#39; jipprova.</td><td>The student failed the Maltese exam, but decided to study more and try again.<br><strong>L-istudent</strong> the student<br><strong>falla</strong> he failed<br><strong>l-eżami tal-Malti</strong> the Maltese exam<br><strong>iżda</strong> but<br><strong>ddeċieda</strong> he decided<br><strong>li jistudja aktar</strong> to study more<br><strong>u jerġa&#39; jipprova</strong> and to try again.</td></tr><tr><td>4. <strong>Ibbukkja</strong> — Qabel is-safra, Mark ibbukkja kamra f&#39;lukanda qrib l-istazzjon biex ikun jista&#39; jivvjaġġa faċilment.</td><td>Before the trip Mark booked a room in a hotel near the station so that he could travel easily.<br><strong>Qabel is-safra</strong> before the trip<br><strong>Mark ibbukkja</strong> Mark booked<br><strong>kamra f&#39;lukanda</strong> a room in a hotel<br><strong>qrib l-istazzjon</strong> near the station<br><strong>biex ikun jista&#39;</strong> so that he could<br><strong>jivvjaġġa faċilment</strong> travel easily.</td></tr><tr><td>5. <strong>Iċċarġja</strong> — Mario iċċarġja l-mowbajl tiegħu qabel ħareġ mid-dar għax kellu bżonn juża l-mappa.</td><td>Mario charged his phone before leaving home because he needed to use the map.<br><strong>Mario iċċarġja</strong> Mario charged<br><strong>l-mowbajl tiegħu</strong> his phone<br><strong>qabel ħareġ</strong> before he went out<br><strong>mid-dar</strong> from home<br><strong>għax kellu bżonn</strong> because he needed<br><strong>juża l-mappa</strong> to use the map.</td></tr><tr><td>6. <strong>Iddefinixxa</strong> — Il-professur iddefinixxa l-kelma l-ġdida u ta żewġ eżempji biex l-istudenti jifhmuha aħjar.</td><td>The professor defined the new word and gave two examples so the students would understand it better.<br><strong>Il-professur</strong> the professor<br><strong>iddefinixxa</strong> he defined<br><strong>l-kelma l-ġdida</strong> the new word<br><strong>u ta</strong> and he gave<br><strong>żewġ eżempji</strong> two examples<br><strong>biex l-istudenti</strong> so that the students<br><strong>jifhmuha aħjar</strong> understand it better, -ha = the word.</td></tr><tr><td>7. <strong>Iffajlja</strong> — L-impjegat iffajlja d-dokumenti tal-klijenti fl-uffiċċju u kiteb id-data fuq kull fajl.</td><td>The employee filed the clients&#39; documents in the office and wrote the date on each file.<br><strong>L-impjegat</strong> the employee<br><strong>iffajlja</strong> he filed<br><strong>d-dokumenti tal-klijenti</strong> the clients&#39; documents<br><strong>fl-uffiċċju</strong> in the office<br><strong>u kiteb</strong> and he wrote<br><strong>id-data</strong> the date<br><strong>fuq kull fajl</strong> on every file.</td></tr><tr><td>8. <strong>Iffavurixxa</strong> — Iffavurixxa lil student wieħed waqt il-logħba, u għalhekk l-oħrajn ħassewhom imdejqin.</td><td>He favoured one student during the game, and so the others felt upset.<br><strong>Iffavurixxa</strong> he favoured, the subject is carried by the verb<br><strong>lil student wieħed</strong> one student<br><strong>waqt il-logħba</strong> during the game<br><strong>u għalhekk</strong> and therefore<br><strong>l-oħrajn</strong> the others<br><strong>ħassewhom imdejqin</strong> they felt upset.</td></tr><tr><td>9. <strong>Iffilmja</strong> — It-turist iffilmja l-festa tar-raħal u bagħat il-filmat lill-familja tiegħu meta wasal id-dar.</td><td>The tourist filmed the village festival and sent the video to his family when he got home.<br><strong>It-turist</strong> the tourist<br><strong>iffilmja</strong> he filmed<br><strong>l-festa tar-raħal</strong> the village festival<br><strong>u bagħat il-filmat</strong> and he sent the video<br><strong>lill-familja tiegħu</strong> to his family<br><strong>meta wasal id-dar</strong> when he got home.</td></tr><tr><td>10. <strong>Ipparkja</strong> — Paul ipparkja l-karozza f&#39;parkeġġ kbir u mexa sal-mużew biex jiltaqa&#39; ma&#39; sħabu.</td><td>Paul parked the car in a large car park and walked to the museum to meet his friends.<br><strong>Paul ipparkja</strong> Paul parked<br><strong>l-karozza</strong> the car<br><strong>f&#39;parkeġġ kbir</strong> in a large car park<br><strong>u mexa</strong> and he walked<br><strong>sal-mużew</strong> to the museum<br><strong>biex jiltaqa&#39;</strong> in order to meet<br><strong>ma&#39; sħabu</strong> with his friends.</td></tr><tr><td>11. <strong>Ippubblika</strong> — Il-kittieb ippubblika ktieb ġdid dwar l-istorja ta&#39; Malta u ppreżentah lill-qarrejja fil-librerija.</td><td>The writer published a new book on the history of Malta and presented it to readers in the library.<br><strong>Il-kittieb</strong> the writer<br><strong>ippubblika</strong> he published<br><strong>ktieb ġdid</strong> a new book<br><strong>dwar l-istorja ta&#39; Malta</strong> about the history of Malta<br><strong>u ppreżentah</strong> and he presented it<br><strong>lill-qarrejja</strong> to the readers<br><strong>fil-librerija</strong> in the library.</td></tr><tr><td>12. <strong>Irreklama</strong> — Is-sid irreklama r-restorant il-ġdid fuq l-internet u offra ikla speċjali lill-ewwel klijenti.</td><td>The owner advertised the new restaurant on the internet and offered a special meal to the first customers.<br><strong>Is-sid</strong> the owner<br><strong>irreklama</strong> he advertised<br><strong>r-restorant il-ġdid</strong> the new restaurant<br><strong>fuq l-internet</strong> on the internet<br><strong>u offra</strong> and he offered<br><strong>ikla speċjali</strong> a special meal<br><strong>lill-ewwel klijenti</strong> to the first customers.</td></tr><tr><td>13. <strong>Iwweldja</strong> — Il-ħaddiem iwweldja żewġ biċċiet tal-metall biex isewwi l-grada l-qadima tad-dar tagħna.</td><td>The worker welded two pieces of metal to repair the old gate of our house.<br><strong>Il-ħaddiem</strong> the worker<br><strong>iwweldja</strong> he welded<br><strong>żewġ biċċiet tal-metall</strong> two pieces of metal<br><strong>biex isewwi</strong> in order to repair<br><strong>l-grada l-qadima</strong> the old gate<br><strong>tad-dar tagħna</strong> of our house.</td></tr><tr><td>14. <strong>Kompla</strong> — Wara waqfa qasira, Joseph kompla jaħdem fuq il-proġett sakemm lesta kollox qabel filgħaxija.</td><td>After a short break Joseph went on working on the project until he finished everything before evening.<br><strong>Wara waqfa qasira</strong> after a short pause<br><strong>Joseph kompla</strong> Joseph continued<br><strong>jaħdem fuq il-proġett</strong> to work on the project<br><strong>sakemm</strong> until<br><strong>lesta kollox</strong> he finished everything<br><strong>qabel filgħaxija</strong> before evening.</td></tr><tr><td>15. <strong>Pinġa</strong> — It-tifel pinġa stampa tal-baħar bil-lapsijiet tal-kulur u taha lil ommu bħala rigal.</td><td>The boy drew a picture of the sea with coloured pencils and gave it to his mother as a present.<br><strong>It-tifel pinġa</strong> the boy drew<br><strong>stampa tal-baħar</strong> a picture of the sea<br><strong>bil-lapsijiet tal-kulur</strong> with coloured pencils<br><strong>u taha</strong> and he gave it<br><strong>lil ommu</strong> to his mother<br><strong>bħala rigal</strong> as a gift.</td></tr><tr><td>16. <strong>Printja</strong> — L-istudent printja l-biljetti tal-ajru u poġġiehom mal-passaport biex ma jinsihomx qabel is-safra.</td><td>The student printed the plane tickets and put them with the passport so as not to forget them before the trip.<br><strong>L-istudent printja</strong> the student printed<br><strong>l-biljetti tal-ajru</strong> the plane tickets<br><strong>u poġġiehom</strong> and he put them<br><strong>mal-passaport</strong> with the passport<br><strong>biex ma jinsihomx</strong> so as not to forget them<br><strong>qabel is-safra</strong> before the trip.</td></tr><tr><td>17. <strong>Skurja</strong> — Il-plejer skurja żewġ gowls fit-tieni taqsima u għen lit-tim tiegħu jirbaħ il-logħba.</td><td>The player scored two goals in the second half and helped his team win the match.<br><strong>Il-plejer skurja</strong> the player scored<br><strong>żewġ gowls</strong> two goals<br><strong>fit-tieni taqsima</strong> in the second half<br><strong>u għen</strong> and he helped<br><strong>lit-tim tiegħu</strong> his team<br><strong>jirbaħ il-logħba</strong> to win the match.</td></tr><tr><td>18. <strong>Studja</strong> — Andrew studja l-Malti għal siegħa kuljum u pprattika t-taħdit ma&#39; ħabib Malti wara x-xogħol.</td><td>Andrew studied Maltese for an hour a day and practised speaking with a Maltese friend after work.<br><strong>Andrew studja</strong> Andrew studied<br><strong>l-Malti</strong> Maltese<br><strong>għal siegħa kuljum</strong> for an hour a day<br><strong>u pprattika</strong> and he practised<br><strong>t-taħdit</strong> speaking<br><strong>ma&#39; ħabib Malti</strong> with a Maltese friend<br><strong>wara x-xogħol</strong> after work.</td></tr></tbody></table><hr><h2 id="_7-the-task-and-the-56-conjugated-forms" tabindex="-1">7 The Task and the 56 Conjugated Forms <a class="header-anchor" href="#_7-the-task-and-the-56-conjugated-forms" aria-label="Permalink to &quot;7 The Task and the 56 Conjugated Forms&quot;">​</a></h2><p><code>Issa agħżel erba&#39; verbi Semitiċi u erbgħa oħra li mhumiex, u kkonjugahom fil-persuni kollha fil-passat</code>: now choose four Semitic verbs and four others that are not, and conjugate them in all persons in the past.</p><p><strong>Issa</strong> now.<br><strong>agħżel</strong> choose.<br><strong>erba&#39; verbi</strong> four verbs.<br><strong>u erbgħa oħra</strong> and four others, where the number stands alone.<br><strong>li mhumiex</strong> that are not of this group.<br><strong>ikkonjugahom</strong> conjugate them, -hom = them.<br><strong>fil-persuni kollha</strong> in all persons.<br><strong>fil-passat</strong> in the past.</p><table tabindex="0"><thead><tr><th>Person</th><th>kiteb write</th><th>fetaħ open</th><th>ħasel wash</th><th>għamel do, make</th></tr></thead><tbody><tr><td>Jien I</td><td>ktibt</td><td>ftaħt</td><td>ħsilt</td><td>għamilt</td></tr><tr><td>Int you</td><td>ktibt</td><td>ftaħt</td><td>ħsilt</td><td>għamilt</td></tr><tr><td>Huwa he</td><td>kiteb</td><td>fetaħ</td><td>ħasel</td><td>għamel</td></tr><tr><td>Hija she</td><td>kitbet</td><td>fetħet</td><td>ħaslet</td><td>għamlet</td></tr><tr><td>Aħna we</td><td>ktibna</td><td>ftaħna</td><td>ħsilna</td><td>għamilna</td></tr><tr><td>Intom you (plural)</td><td>ktibtu</td><td>ftaħtu</td><td>ħsiltu</td><td>għamiltu</td></tr><tr><td>Huma they</td><td>kitbu</td><td>fetħu</td><td>ħaslu</td><td>għamlu</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Person</th><th>aċċetta accept</th><th>ibbukkja book</th><th>ipparkja park</th><th>studja study</th></tr></thead><tbody><tr><td>Jien I</td><td>aċċettajt</td><td>ibbukkjajt</td><td>ipparkjajt</td><td>studjajt</td></tr><tr><td>Int you</td><td>aċċettajt</td><td>ibbukkjajt</td><td>ipparkjajt</td><td>studjajt</td></tr><tr><td>Huwa he</td><td>aċċetta</td><td>ibbukkja</td><td>ipparkja</td><td>studja</td></tr><tr><td>Hija she</td><td>aċċettat</td><td>ibbukkjat</td><td>ipparkjat</td><td>studjat</td></tr><tr><td>Aħna we</td><td>aċċettajna</td><td>ibbukkjajna</td><td>ipparkjajna</td><td>studjajna</td></tr><tr><td>Intom you (plural)</td><td>aċċettajtu</td><td>ibbukkjajtu</td><td>ipparkjajtu</td><td>studjajtu</td></tr><tr><td>Huma they</td><td>aċċettaw</td><td>ibbukkjaw</td><td>ipparkjaw</td><td>studjaw</td></tr></tbody></table><p>The first and second person singular are often identical and must be told apart by the subject and the context; for example <strong>ktibt</strong> = I wrote / you wrote. <strong>-na</strong> usually marks &quot;we&quot; and <strong>-tu</strong> &quot;you (plural)&quot;, but endings cannot simply be glued onto every base form; note <strong>kiteb → ktibna</strong> and <strong>għamel → għamilna</strong>. The third person plural often ends in <strong>-u / -w</strong>. The two tables hold eight verbs with seven persons each.</p><hr><h2 id="_8-oral-topics" tabindex="-1">8 Oral Topics <a class="header-anchor" href="#_8-oral-topics" aria-label="Permalink to &quot;8 Oral Topics&quot;">​</a></h2><p><code>It-Taħdit</code> speaking. <code>Iddeskrivi l-aħħar darba li sifirt</code> describe the last time you travelled abroad. <strong>Iddeskrivi</strong> describe; <strong>l-aħħar darba</strong> the last time; <strong>li sifirt</strong> that you travelled. The fictional trip to Italy is used as the example.</p><h3 id="topic-one-my-last-trip-question-by-question" tabindex="-1">Topic One: My Last Trip, Question by Question <a class="header-anchor" href="#topic-one-my-last-trip-question-by-question" aria-label="Permalink to &quot;Topic One: My Last Trip, Question by Question&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prompt and fairly full answer</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>Meta mort? — Mort l-Italja f&#39;April li għadda u qattajt hemm ġimgħa waqt il-vaganzi.</td><td>When did you go? — I went to Italy last April and spent a week there during the holidays.<br><strong>Meta mort</strong> when did you go<br><strong>Mort l-Italja</strong> I went to Italy<br><strong>f&#39;April li għadda</strong> last April<br><strong>u qattajt</strong> and I spent<br><strong>hemm ġimgħa</strong> a week there<br><strong>waqt il-vaganzi</strong> during the holidays.</td></tr><tr><td>Fejn mort? — Żort Ruma u Firenze, fejn rajt mużewijiet, knejjes antiki u pjazez sbieħ.</td><td>Where did you go? — I visited Rome and Florence, where I saw museums, old churches and beautiful squares.<br><strong>Fejn mort</strong> where did you go<br><strong>Żort</strong> I visited<br><strong>Ruma u Firenze</strong> Rome and Florence<br><strong>fejn rajt</strong> where I saw<br><strong>mużewijiet</strong> museums<br><strong>knejjes antiki</strong> old churches<br><strong>u pjazez sbieħ</strong> and beautiful squares.</td></tr><tr><td>Ma&#39; min mort? — Mort ma&#39; żewġ ħbieb tal-kors u qsamna kamra f&#39;lukanda żgħira.</td><td>With whom did you go? — With two friends from the course, and we shared a room in a small hotel.<br><strong>Ma&#39; min</strong> with whom<br><strong>Mort ma&#39;</strong> I went with<br><strong>żewġ ħbieb tal-kors</strong> two friends from the course<br><strong>u qsamna</strong> and we shared<br><strong>kamra</strong> a room<br><strong>f&#39;lukanda żgħira</strong> in a small hotel.</td></tr><tr><td>Liema mezz tat-trasport użajt? — Ħadt l-ajruplan minn Malta u użajt il-ferrovija biex nivvjaġġa bejn il-bliet.</td><td>Which means of transport did you use? — I flew from Malta and used the train to travel between the cities.<br><strong>Liema mezz tat-trasport</strong> which means of transport<br><strong>użajt</strong> you used / I used<br><strong>Ħadt l-ajruplan</strong> I took the plane<br><strong>minn Malta</strong> from Malta<br><strong>u użajt il-ferrovija</strong> and I used the train<br><strong>biex nivvjaġġa</strong> in order to travel<br><strong>bejn il-bliet</strong> between the cities.</td></tr><tr><td>Iddeskrivi l-postijiet li żort. — Ruma kienet kbira u storika, waqt li Firenze kienet sabiħa u mimlija arti.</td><td>Describe the places you visited. — Rome was big and full of history, while Florence was beautiful and full of art.<br><strong>l-postijiet li żort</strong> the places you visited<br><strong>Ruma kienet</strong> Rome was<br><strong>kbira u storika</strong> big and historic<br><strong>waqt li</strong> while<br><strong>Firenze kienet sabiħa</strong> Florence was beautiful<br><strong>u mimlija arti</strong> and full of art.</td></tr><tr><td>Liema l-iktar ħaġa li għoġbitek? — L-iktar li għoġobni kien il-katidral ta&#39; Firenze għax il-bini tiegħu huwa impressjonanti.</td><td>Which thing did you like most? — Florence Cathedral, because its building is impressive.<br><strong>Liema l-iktar ħaġa</strong> which thing most<br><strong>li għoġbitek</strong> that you liked<br><strong>L-iktar li għoġobni</strong> what I liked most<br><strong>kien il-katidral ta&#39; Firenze</strong> was Florence Cathedral<br><strong>għax</strong> because<br><strong>il-bini tiegħu</strong> its building<br><strong>huwa impressjonanti</strong> is impressive.</td></tr><tr><td>Kien hemm xi ħaġa li dejqitek? — Iva, il-kjuwijiet twal dejquni, speċjalment meta kellna nistennew barra fix-xemx.</td><td>Was there anything that annoyed you? — Yes, the long queues annoyed me, especially when we had to wait outside in the sun.<br><strong>Kien hemm</strong> was there<br><strong>xi ħaġa li dejqitek</strong> something that annoyed you<br><strong>Iva</strong> yes<br><strong>il-kjuwijiet twal</strong> the long queues<br><strong>dejquni</strong> they annoyed me, -ni = me<br><strong>speċjalment meta</strong> especially when<br><strong>kellna nistennew</strong> we had to wait<br><strong>barra fix-xemx</strong> outside in the sun.</td></tr><tr><td>Inqalgħet xi problema? — Darba tlifna l-ferrovija, iżda sibna oħra u wasalna fil-lukanda qabel filgħaxija.</td><td>Did any problem come up? — Once we missed the train, but we found another one and reached the hotel before evening.<br><strong>Inqalgħet</strong> it arose<br><strong>xi problema</strong> some problem<br><strong>Darba</strong> once<br><strong>tlifna l-ferrovija</strong> we missed the train<br><strong>iżda sibna oħra</strong> but we found another one<br><strong>u wasalna fil-lukanda</strong> and we reached the hotel<br><strong>qabel filgħaxija</strong> before evening.</td></tr></tbody></table><h3 id="topic-two-my-favourite-place" tabindex="-1">Topic Two: My Favourite Place <a class="header-anchor" href="#topic-two-my-favourite-place" aria-label="Permalink to &quot;Topic Two: My Favourite Place&quot;">​</a></h3><p><code>Iddeskrivi l-post favorit tiegħek</code> describe your favourite place; <strong>il-post</strong> the place, <strong>favorit tiegħek</strong> your favourite. The Mellieħa beach in Malta is used here.</p><table tabindex="0"><thead><tr><th>Prompt and answer</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>Fejn jinsab dan il-post? F&#39;liema pajjiż? — Il-post favorit tiegħi huwa l-bajja tal-Mellieħa, fit-tramuntana ta&#39; Malta.</td><td>Where is this place? In which country? — My favourite place is Mellieħa Bay, in the north of Malta.<br><strong>Fejn jinsab</strong> where is it located<br><strong>dan il-post</strong> this place<br><strong>F&#39;liema pajjiż</strong> in which country<br><strong>Il-post favorit tiegħi</strong> my favourite place<br><strong>huwa l-bajja tal-Mellieħa</strong> is Mellieħa Bay<br><strong>fit-tramuntana ta&#39; Malta</strong> in the north of Malta.</td></tr><tr><td>Ġewwa jew barra? — Huwa post fil-beraħ, fejn nista&#39; nimxi fuq ir-ramel u ngħum fil-baħar.</td><td>Inside or outside? — It is an open-air place, where I can walk on the sand and swim in the sea.<br><strong>Ġewwa jew barra</strong> inside or outside<br><strong>Huwa post fil-beraħ</strong> it is an open-air place<br><strong>fejn nista&#39;</strong> where I can<br><strong>nimxi fuq ir-ramel</strong> walk on the sand<br><strong>u ngħum fil-baħar</strong> and swim in the sea.</td></tr><tr><td>Tmur spiss hemmhekk? — Fis-sajf immur hemm darba fil-ġimgħa, ġeneralment il-Ħadd filgħodu ma&#39; sħabi.</td><td>Do you go there often? — In summer I go once a week, usually on Sunday morning with my friends.<br><strong>Tmur spiss</strong> do you go often<br><strong>hemmhekk</strong> there<br><strong>Fis-sajf</strong> in summer<br><strong>immur hemm</strong> I go there<br><strong>darba fil-ġimgħa</strong> once a week<br><strong>ġeneralment</strong> generally<br><strong>il-Ħadd filgħodu</strong> Sunday morning<br><strong>ma&#39; sħabi</strong> with my friends.</td></tr><tr><td>Għaliex jogħġbok? — Jogħġobni għax nista&#39; nistrieħ, nieħu arja friska u nqatta&#39; ħin mal-ħbieb.</td><td>Why do you like it? — I like it because I can rest, get fresh air and spend time with friends.<br><strong>Għaliex</strong> why<br><strong>jogħġbok / jogħġobni</strong> it pleases you / it pleases me, referring back to post<br><strong>għax nista&#39;</strong> because I can<br><strong>nistrieħ</strong> rest<br><strong>nieħu arja friska</strong> get fresh air<br><strong>u nqatta&#39; ħin</strong> and spend time<br><strong>mal-ħbieb</strong> with friends.</td></tr><tr><td>X&#39;aġġettivi tista&#39; tuża biex tiddeskrivi dan il-post? — Nista&#39; ngħid li huwa sabiħ, spazjuż u kwiet kmieni filgħodu.</td><td>Which adjectives can you use to describe this place? — I can say it is beautiful, spacious and quiet early in the morning.<br><strong>X&#39;aġġettivi</strong> which adjectives<br><strong>tista&#39; tuża</strong> you can use<br><strong>biex tiddeskrivi</strong> to describe<br><strong>dan il-post</strong> this place<br><strong>Nista&#39; ngħid li</strong> I can say that<br><strong>huwa sabiħ, spazjuż u kwiet</strong> it is beautiful, spacious and quiet, all with post<br><strong>kmieni filgħodu</strong> early in the morning.</td></tr><tr><td>X&#39;tista&#39; tara u tisma&#39; meta tkun hemm? — Nara l-baħar blu u d-dgħajjes, u nisma&#39; l-mewġ u t-tfal jilagħbu.</td><td>What can you see and hear when you are there? — I see the blue sea and the boats, and I hear the waves and children playing.<br><strong>X&#39;tista&#39; tara u tisma&#39;</strong> what can you see and hear<br><strong>meta tkun hemm</strong> when you are there<br><strong>Nara</strong> I see<br><strong>l-baħar blu u d-dgħajjes</strong> the blue sea and the boats<br><strong>u nisma&#39;</strong> and I hear<br><strong>l-mewġ</strong> the waves<br><strong>u t-tfal jilagħbu</strong> and children playing.</td></tr><tr><td>Xi tħoss meta tkun hemm? — Meta nkun hemm inħossni kalm u ferħan, u ninsa ftit l-istress tax-xogħol.</td><td>How do you feel when you are there? — When I am there I feel calm and happy, and I forget the work stress for a while.<br><strong>Xi tħoss</strong> what do you feel<br><strong>meta tkun hemm</strong> when you are there<br><strong>Meta nkun hemm</strong> when I am there<br><strong>inħossni</strong> I feel, -ni reflexive<br><strong>kalm u ferħan</strong> calm and happy, masculine speaker; feminine kalma u ferħana<br><strong>u ninsa ftit</strong> and I forget for a while<br><strong>l-istress tax-xogħol</strong> work stress.</td></tr></tbody></table><hr><h2 id="_9-writing-a-trip" tabindex="-1">9 Writing: A Trip <a class="header-anchor" href="#_9-writing-a-trip" aria-label="Permalink to &quot;9 Writing: A Trip&quot;">​</a></h2><p><code>Il-Kitba – Agħżel waħda minn pg. 7 u ikteb ftit sentenzi dwarha</code>: writing — choose one topic and write a few sentences about it. <strong>Agħżel</strong> choose; <strong>waħda</strong> one; <strong>minn</strong> from; <strong>ikteb</strong> write; <strong>ftit sentenzi</strong> a few sentences; <strong>dwarha</strong> about it. <code>pg. 7</code> is an old reference; in this booklet it is page 8.</p><h3 id="a-connected-model-text" tabindex="-1">A Connected Model Text <a class="header-anchor" href="#a-connected-model-text" aria-label="Permalink to &quot;A Connected Model Text&quot;">​</a></h3><p>F&#39;April li għadda mort l-Italja ma&#39; żewġ ħbieb tal-kors. Ħadna l-ajruplan minn Malta u mbagħad il-ferrovija bejn Ruma u Firenze. Qgħadna f&#39;lukanda żgħira qrib iċ-ċentru u mxejna ħafna kuljum. F&#39;Ruma żorna mużew u rajna ħafna bini antik, waqt li f&#39;Firenze għoġobna ħafna l-katidral. L-ikel kien mill-aqwa, speċjalment l-għaġin, u wara l-pranzu dejjem kilna ġelat. Darba tlifna l-ferrovija, iżda stennejna oħra u ma kellniex problemi kbar. L-iktar ħaġa li għoġbitni kienet li qattajt ħin sabiħ ma&#39; sħabi. Nixtieq nerġa&#39; mmur hemm u nżur postijiet oħra li ma rajtx din id-darba.</p><table tabindex="0"><thead><tr><th>Sentence from the model text</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>F&#39;April li għadda mort l-Italja ma&#39; żewġ ħbieb tal-kors.</td><td>Last April I went to Italy with two friends from the course.<br><strong>F&#39;April li għadda</strong> last April<br><strong>mort</strong> I went<br><strong>l-Italja</strong> Italy<br><strong>ma&#39; żewġ ħbieb</strong> with two friends<br><strong>tal-kors</strong> of the course.</td></tr><tr><td>Ħadna l-ajruplan minn Malta u mbagħad il-ferrovija bejn Ruma u Firenze.</td><td>We took the plane from Malta and then the train between Rome and Florence.<br><strong>Ħadna</strong> we took<br><strong>l-ajruplan</strong> the plane<br><strong>minn Malta</strong> from Malta<br><strong>u mbagħad</strong> and then<br><strong>il-ferrovija</strong> the train<br><strong>bejn Ruma u Firenze</strong> between Rome and Florence.</td></tr><tr><td>Qgħadna f&#39;lukanda żgħira qrib iċ-ċentru u mxejna ħafna kuljum.</td><td>We stayed in a small hotel near the centre and walked a lot every day.<br><strong>Qgħadna</strong> we stayed<br><strong>f&#39;lukanda żgħira</strong> in a small hotel<br><strong>qrib iċ-ċentru</strong> near the centre<br><strong>u mxejna</strong> and we walked<br><strong>ħafna kuljum</strong> a lot every day.</td></tr><tr><td>F&#39;Ruma żorna mużew u rajna ħafna bini antik, waqt li f&#39;Firenze għoġobna ħafna l-katidral.</td><td>In Rome we visited a museum and saw a lot of old buildings, while in Florence we liked the cathedral very much.<br><strong>F&#39;Ruma</strong> in Rome<br><strong>żorna mużew</strong> we visited a museum<br><strong>u rajna ħafna bini antik</strong> and we saw a lot of old buildings<br><strong>waqt li</strong> while<br><strong>f&#39;Firenze</strong> in Florence<br><strong>għoġobna ħafna</strong> we liked very much, -na = we<br><strong>l-katidral</strong> the cathedral.</td></tr><tr><td>L-ikel kien mill-aqwa, speċjalment l-għaġin, u wara l-pranzu dejjem kilna ġelat.</td><td>The food was excellent, especially the pasta, and after lunch we always had ice cream.<br><strong>L-ikel</strong> the food<br><strong>kien mill-aqwa</strong> was excellent<br><strong>speċjalment l-għaġin</strong> especially the pasta<br><strong>u wara l-pranzu</strong> and after lunch<br><strong>dejjem</strong> always<br><strong>kilna ġelat</strong> we ate ice cream.</td></tr><tr><td>Darba tlifna l-ferrovija, iżda stennejna oħra u ma kellniex problemi kbar.</td><td>Once we missed the train, but we waited for another one and had no big problems.<br><strong>Darba</strong> once<br><strong>tlifna l-ferrovija</strong> we missed the train<br><strong>iżda stennejna oħra</strong> but we waited for another one<br><strong>u ma kellniex</strong> and we did not have<br><strong>problemi kbar</strong> big problems.</td></tr><tr><td>L-iktar ħaġa li għoġbitni kienet li qattajt ħin sabiħ ma&#39; sħabi.</td><td>What I liked most was spending pleasant time with my friends.<br><strong>L-iktar ħaġa</strong> the thing most<br><strong>li għoġbitni</strong> that I liked<br><strong>kienet li</strong> was that<br><strong>qattajt ħin sabiħ</strong> I spent pleasant time<br><strong>ma&#39; sħabi</strong> with my friends.</td></tr><tr><td>Nixtieq nerġa&#39; mmur hemm u nżur postijiet oħra li ma rajtx din id-darba.</td><td>I would like to go there again and visit other places I did not see this time.<br><strong>Nixtieq</strong> I would like<br><strong>nerġa&#39; mmur</strong> to go again<br><strong>hemm</strong> there<br><strong>u nżur postijiet oħra</strong> and visit other places<br><strong>li ma rajtx</strong> that I did not see<br><strong>din id-darba</strong> this time.</td></tr></tbody></table><hr><h2 id="_10-an-informal-letter-ten-blanks" tabindex="-1">10 An Informal Letter: Ten Blanks <a class="header-anchor" href="#_10-an-informal-letter-ten-blanks" aria-label="Permalink to &quot;10 An Informal Letter: Ten Blanks&quot;">​</a></h2><p>Order of the answers: <strong>tajba → ħadna → morna → żorna → tlajt → l-ogħla → mill-aqwa → kilna → xtaqt → prova</strong>. Each word is used once.</p><p>The instruction in short: complete the informal letter with the verbs and adjectives given below; imagine you are writing to a female friend to tell her what you did and what happened on your last trip.</p><p><strong>Ittra Informali</strong> informal letter.<br><strong>Imla l-vojt</strong> fill in the gap.<br><strong>bil-verbi u l-aġġettivi</strong> with the verbs and the adjectives.<br><strong>li hemm taħt</strong> that are given below.<br><strong>Immaġina</strong> imagine.<br><strong>li se tibgħat</strong> that you are going to send.<br><strong>lil ħabibtek</strong> to your female friend.<br><strong>sabiex tgħidilha</strong> in order to tell her.<br><strong>x&#39;għamilt u x&#39;ġara</strong> what you did and what happened.<br><strong>waqt vaganza</strong> during a holiday.<br><strong>li mort ftit ilu</strong> that you went on a short while ago.</p><h3 id="the-completed-letter" tabindex="-1">The Completed Letter <a class="header-anchor" href="#the-completed-letter" aria-label="Permalink to &quot;The Completed Letter&quot;">​</a></h3><p>22, Viv, Triq it-Tagħlim, Il-Fgura FGR2144</p><p>Għażiża Laura,</p><p>Kif int? Jien ninsab tajba u nixtieq nirrakkuntalek daqsxejn x&#39;għamilna Spanja! Kemm ħadna gost u kemm hemm x&#39;tara!</p><p>L-ewwel post li morna kien Barċellona, imbagħad għamilna l-aħħar jumejn tal-vaganza ġewwa Girona u Tossa del Mar. Żorna l-Akkwarju ta&#39; Barċellona, is-Sagrada Famiglia, Parc Guell u Portaventura! Hemm tlajt fuq l-ogħla rollercoaster li qatt irkibt! Kemm werżaqna mill-qalb! L-ikel huwa mill-aqwa wkoll, kilna ħafna paella u tapas tradizzjonali Spanjoli.</p><p>Veru xtaqt li kont magħna Laura u tgħidx kemm semmejniek! Issa prova ejja magħna l-vaganza li jmiss, ħa mmorru Ċipru nduru l-bajjiet sbieħ t&#39;hemm.</p><p>Ċaw!</p><p>Tania</p><h3 id="sentence-analysis" tabindex="-1">Sentence Analysis <a class="header-anchor" href="#sentence-analysis" aria-label="Permalink to &quot;Sentence Analysis&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Original sentences</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>Għażiża Laura, / Kif int?</td><td>Dear Laura, / How are you?<br><strong>Għażiża</strong> dear, for a female addressee<br><strong>Laura</strong> a name<br><strong>Kif</strong> how<br><strong>int</strong> you.</td></tr><tr><td>Jien ninsab tajba u nixtieq nirrakkuntalek daqsxejn x&#39;għamilna Spanja!</td><td>I am well and I would like to tell you a little about what we did in Spain!<br><strong>Jien</strong> I<br><strong>ninsab tajba</strong> I am in a good state, female speaker<br><strong>u nixtieq</strong> and I would like<br><strong>nirrakkuntalek</strong> to tell you, -lek = to you<br><strong>daqsxejn</strong> a little<br><strong>x&#39;għamilna</strong> what we did<br><strong>Spanja</strong> in Spain.</td></tr><tr><td>Kemm ħadna gost u kemm hemm x&#39;tara!</td><td>How much fun we had, and how much there is to see!<br><strong>Kemm</strong> how much, exclamation<br><strong>ħadna gost</strong> we had fun<br><strong>u kemm hemm</strong> and how much there is<br><strong>x&#39;tara</strong> to see.</td></tr><tr><td>L-ewwel post li morna kien Barċellona, imbagħad għamilna l-aħħar jumejn tal-vaganza ġewwa Girona u Tossa del Mar.</td><td>The first place we went to was Barcelona, then we spent the last two days of the holiday in Girona and Tossa del Mar.<br><strong>L-ewwel post</strong> the first place<br><strong>li morna</strong> that we went to; a fuller form is li morna fih<br><strong>kien Barċellona</strong> was Barcelona<br><strong>imbagħad</strong> then<br><strong>għamilna</strong> we spent; here not &quot;we made&quot;<br><strong>l-aħħar jumejn</strong> the last two days, a dual form<br><strong>tal-vaganza</strong> of the holiday<br><strong>ġewwa</strong> in<br><strong>Girona u Tossa del Mar</strong> two place names.</td></tr><tr><td>Żorna l-Akkwarju ta&#39; Barċellona, is-Sagrada Famiglia, Parc Guell u Portaventura!</td><td>We visited the Barcelona Aquarium, the Sagrada Famiglia, Parc Guell and Portaventura!<br><strong>Żorna</strong> we visited<br><strong>l-Akkwarju</strong> the aquarium<br><strong>ta&#39; Barċellona</strong> of Barcelona<br><strong>is-Sagrada Famiglia / Parc Guell / Portaventura</strong> the textbook&#39;s spellings of the sights<br><strong>u</strong> and.</td></tr><tr><td>Hemm tlajt fuq l-ogħla rollercoaster li qatt irkibt!</td><td>There I went on the highest rollercoaster I have ever ridden!<br><strong>Hemm</strong> there<br><strong>tlajt fuq</strong> I got on<br><strong>l-ogħla</strong> the highest<br><strong>rollercoaster</strong> rollercoaster, borrowed from English<br><strong>li qatt irkibt</strong> that I ever rode.</td></tr><tr><td>Kemm werżaqna mill-qalb!</td><td>How we screamed, with all our heart!<br><strong>Kemm</strong> how<br><strong>werżaqna</strong> we screamed<br><strong>mill-qalb</strong> from the heart, wholeheartedly.</td></tr><tr><td>L-ikel huwa mill-aqwa wkoll, kilna ħafna paella u tapas tradizzjonali Spanjoli.</td><td>The food is excellent too; we ate a lot of paella and traditional Spanish tapas.<br><strong>L-ikel</strong> the food<br><strong>huwa mill-aqwa</strong> is excellent<br><strong>wkoll</strong> also, the variant ukoll<br><strong>kilna ħafna</strong> we ate a lot<br><strong>paella u tapas</strong> paella and tapas<br><strong>tradizzjonali Spanjoli</strong> traditional Spanish.</td></tr><tr><td>Veru xtaqt li kont magħna Laura u tgħidx kemm semmejniek!</td><td>Laura, I really wished you had been with us, and you can&#39;t imagine how often we mentioned you!<br><strong>Veru</strong> really<br><strong>xtaqt</strong> I wished<br><strong>li kont magħna</strong> that you were with us; a wish, not a claim that she came<br><strong>u tgħidx kemm</strong> don&#39;t say how much, an exclamatory idiom<br><strong>semmejniek</strong> we mentioned you, -k = you.</td></tr><tr><td>Issa prova ejja magħna l-vaganza li jmiss, ħa mmorru Ċipru nduru l-bajjiet sbieħ t&#39;hemm.</td><td>Now try to come with us on the next holiday; let us go to Cyprus and go round the beautiful beaches there.<br><strong>Issa</strong> now / so<br><strong>prova</strong> try, imperative<br><strong>ejja magħna</strong> come with us<br><strong>l-vaganza li jmiss</strong> the next holiday<br><strong>ħa mmorru</strong> let us go / we are going to go<br><strong>Ċipru</strong> Cyprus<br><strong>nduru</strong> we go round<br><strong>l-bajjiet sbieħ</strong> the beautiful beaches<br><strong>t&#39;hemm</strong> of there.</td></tr><tr><td>Ċaw! / Tania</td><td>Bye! / Tania.<br><strong>Ċaw</strong> informal hello / goodbye<br><strong>Tania</strong> the writer&#39;s signature.</td></tr></tbody></table><p>In the address <strong>Triq it-Tagħlim</strong> = &quot;Learning Street&quot;, <strong>Il-Fgura</strong> is a place name, <strong>FGR2144</strong> is the textbook&#39;s postcode; <strong>Viv</strong> is the name of the house and is not translated.</p><hr><h2 id="_11-a-complete-model-letter-to-a-cousin" tabindex="-1">11 A Complete Model Letter to a Cousin <a class="header-anchor" href="#_11-a-complete-model-letter-to-a-cousin" aria-label="Permalink to &quot;11 A Complete Model Letter to a Cousin&quot;">​</a></h2><p>The task: write an informal letter to a female cousin describing the places you saw on your last holiday, using the travel prompts.</p><p><strong>Ikteb ittra informali</strong> write an informal letter.<br><strong>lill-kuġina</strong> to the female cousin.<br><strong>sabiex tiddeskrivi</strong> in order to describe.<br><strong>l-postijiet li rajt</strong> the places you saw.<br><strong>waqt il-vaganza li għaddiet</strong> during the last holiday.<br><strong>Uża l-punti</strong> use the points.<br><strong>minn paġna 7</strong> an old page reference; the content is on page 8 of this file.<br><strong>biex jgħinuk</strong> so that they help you.</p><p>37, Ward u Żahar<br> Triq il-Fjuri<br> Ħad-Dingli<br> DNG 1682</p><p>L-1 ta&#39; Awwissu, 2023</p><p>Għażiża Maria,</p><p>Kif int? Nispera li inti u l-familja tinsabu tajbin. Għadni kif ġejt lura minn vaganza sabiħa fl-Italja u nixtieq ngħidlek x&#39;rajt hemmhekk.</p><p>Mort ma&#39; żewġ ħbieb tiegħi u qattajna ġimgħa bejn Ruma u Firenze. Sifirna bl-ajruplan minn Malta u wara użajna l-ferrovija. F&#39;Ruma żorna mużewijiet u mxejna fit-toroq antiki qrib iċ-ċentru. L-iktar li għoġobni kien il-katidral ta&#39; Firenze għax huwa kbir u mimli dettalji sbieħ. Ħadna ħafna ritratti u kull filgħaxija kilna f&#39;restorant differenti. L-għaġin kien mill-aqwa, u dejjem ħallejna ftit spazju għall-ġelat.</p><p>Darba bdiet ix-xita waqt il-mixja, iżda sibna kafetterija u stennejna hemm. Ma ħallejniex it-temp iħassar il-ġurnata, u wara komplejna nduru bil-ferħ. Nixtieq nerġa&#39; mmur l-Italja fil-futur, u nittama li d-darba li jmiss tiġi magħna.</p><p>Iktibli meta jkollok ftit ħin u għidli kif qattajt il-vaganza tiegħek.</p><p>Insellimlek,</p><p>Anna</p><h3 id="sentence-analysis-1" tabindex="-1">Sentence Analysis <a class="header-anchor" href="#sentence-analysis-1" aria-label="Permalink to &quot;Sentence Analysis&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sentence from the model text</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>Għażiża Maria, Kif int? Nispera li inti u l-familja tinsabu tajbin.</td><td>Dear Maria, how are you? I hope you and the family are well.<br><strong>Għażiża</strong> dear, feminine<br><strong>Kif int</strong> how are you<br><strong>Nispera li</strong> I hope that<br><strong>inti u l-familja</strong> you and the family<br><strong>tinsabu tajbin</strong> you are well, plural.</td></tr><tr><td>Għadni kif ġejt lura minn vaganza sabiħa fl-Italja u nixtieq ngħidlek x&#39;rajt hemmhekk.</td><td>I have just come back from a lovely holiday in Italy and I would like to tell you what I saw there.<br><strong>Għadni kif</strong> I have just<br><strong>ġejt lura</strong> come back<br><strong>minn vaganza sabiħa</strong> from a lovely holiday<br><strong>fl-Italja</strong> in Italy<br><strong>u nixtieq</strong> and I would like<br><strong>ngħidlek</strong> to tell you<br><strong>x&#39;rajt</strong> what I saw<br><strong>hemmhekk</strong> there.</td></tr><tr><td>Mort ma&#39; żewġ ħbieb tiegħi u qattajna ġimgħa bejn Ruma u Firenze.</td><td>I went with two of my friends and we spent a week between Rome and Florence.<br><strong>Mort</strong> I went<br><strong>ma&#39; żewġ ħbieb tiegħi</strong> with two of my friends<br><strong>u qattajna</strong> and we spent<br><strong>ġimgħa</strong> a week<br><strong>bejn Ruma u Firenze</strong> between the two cities.</td></tr><tr><td>Sifirna bl-ajruplan minn Malta u wara użajna l-ferrovija.</td><td>We flew from Malta and then used the train.<br><strong>Sifirna</strong> we travelled<br><strong>bl-ajruplan</strong> by plane<br><strong>minn Malta</strong> from Malta<br><strong>u wara</strong> and then<br><strong>użajna l-ferrovija</strong> we used the train.</td></tr><tr><td>F&#39;Ruma żorna mużewijiet u mxejna fit-toroq antiki qrib iċ-ċentru.</td><td>In Rome we visited museums and walked along the old streets near the centre.<br><strong>F&#39;Ruma</strong> in Rome<br><strong>żorna mużewijiet</strong> we visited museums<br><strong>u mxejna</strong> and we walked<br><strong>fit-toroq antiki</strong> in the old streets<br><strong>qrib iċ-ċentru</strong> near the centre.</td></tr><tr><td>L-iktar li għoġobni kien il-katidral ta&#39; Firenze għax huwa kbir u mimli dettalji sbieħ.</td><td>What I liked most was Florence Cathedral, because it is big and full of beautiful details.<br><strong>L-iktar li għoġobni</strong> what I liked most<br><strong>kien il-katidral ta&#39; Firenze</strong> was Florence Cathedral<br><strong>għax huwa kbir</strong> because it is big<br><strong>u mimli</strong> and full<br><strong>dettalji sbieħ</strong> of beautiful details.</td></tr><tr><td>Ħadna ħafna ritratti u kull filgħaxija kilna f&#39;restorant differenti.</td><td>We took a lot of photos and every evening we ate in a different restaurant.<br><strong>Ħadna ħafna ritratti</strong> we took a lot of photos<br><strong>u kull filgħaxija</strong> and every evening<br><strong>kilna</strong> we ate<br><strong>f&#39;restorant differenti</strong> in a different restaurant.</td></tr><tr><td>L-għaġin kien mill-aqwa, u dejjem ħallejna ftit spazju għall-ġelat.</td><td>The pasta was excellent, and we always left a little room for ice cream.<br><strong>L-għaġin</strong> the pasta<br><strong>kien mill-aqwa</strong> was excellent<br><strong>u dejjem ħallejna</strong> and we always left<br><strong>ftit spazju</strong> a little space<br><strong>għall-ġelat</strong> for ice cream.</td></tr><tr><td>Darba bdiet ix-xita waqt il-mixja, iżda sibna kafetterija u stennejna hemm.</td><td>Once it started raining during the walk, but we found a café and waited there.<br><strong>Darba</strong> once<br><strong>bdiet ix-xita</strong> it started raining<br><strong>waqt il-mixja</strong> during the walk<br><strong>iżda sibna kafetterija</strong> but we found a café<br><strong>u stennejna hemm</strong> and we waited there.</td></tr><tr><td>Ma ħallejniex it-temp iħassar il-ġurnata, u wara komplejna nduru bil-ferħ.</td><td>We did not let the weather ruin the day, and afterwards we went on touring happily.<br><strong>Ma ħallejniex</strong> we did not let<br><strong>it-temp</strong> the weather<br><strong>iħassar il-ġurnata</strong> ruin the day<br><strong>u wara</strong> and afterwards<br><strong>komplejna nduru</strong> we went on touring<br><strong>bil-ferħ</strong> happily.</td></tr><tr><td>Nixtieq nerġa&#39; mmur l-Italja fil-futur, u nittama li d-darba li jmiss tiġi magħna.</td><td>I would like to go to Italy again in the future, and I hope that next time you will come with us.<br><strong>Nixtieq nerġa&#39; mmur</strong> I would like to go again<br><strong>l-Italja fil-futur</strong> to Italy in the future<br><strong>u nittama li</strong> and I hope that<br><strong>d-darba li jmiss</strong> the next time<br><strong>tiġi magħna</strong> you come with us.</td></tr><tr><td>Iktibli meta jkollok ftit ħin u għidli kif qattajt il-vaganza tiegħek.</td><td>Write to me when you have a little time and tell me how you spent your holiday.<br><strong>Iktibli</strong> write to me<br><strong>meta jkollok ftit ħin</strong> when you have a little time<br><strong>u għidli</strong> and tell me<br><strong>kif qattajt</strong> how you spent<br><strong>il-vaganza tiegħek</strong> your holiday.</td></tr><tr><td>Insellimlek, Anna</td><td>Greetings, Anna.<br><strong>Insellimlek</strong> I greet you, an informal closing<br><strong>Anna</strong> a fictional signature.</td></tr></tbody></table><p>The address keeps the exercise&#39;s own details: <strong>Ward u Żahar</strong> is the name of the house, readable as an image of flowers and blossom; <strong>Triq il-Fjuri</strong> = Street of Flowers; <strong>Ħad-Dingli</strong> = the place Dingli; <strong>DNG 1682</strong> = the postcode. <strong>L-1 ta&#39; Awwissu, 2023</strong> = 1 August 2023, the exercise&#39;s date, not changed to today.</p><hr><h2 id="_12-matching-the-means-of-transport" tabindex="-1">12 Matching the Means of Transport <a class="header-anchor" href="#_12-matching-the-means-of-transport" aria-label="Permalink to &quot;12 Matching the Means of Transport&quot;">​</a></h2><p>Exercise <code>Qabbel il-mezz ta&#39; trasport li jintuża f&#39;din is-sitwazzjoni</code>: match the means of transport used in this situation. <strong>Qabbel</strong> match; <strong>il-mezz ta&#39; trasport</strong> the means of transport; <strong>li jintuża</strong> that is used; <strong>f&#39;din is-sitwazzjoni</strong> in this situation.</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td>rota</td><td>bicycle</td></tr><tr><td>ferrovija</td><td>train</td></tr><tr><td>taxi</td><td>taxi</td></tr><tr><td>vapur</td><td>ship, boat</td></tr><tr><td>tal-linja</td><td>bus; the full form is karozza tal-linja</td></tr><tr><td>ajruplan</td><td>plane</td></tr><tr><td>karozza</td><td>car</td></tr><tr><td>vann</td><td>van</td></tr><tr><td>mutur</td><td>motorbike</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Original sentence and match</th><th>Translation and word-by-word notes</th></tr></thead><tbody><tr><td>1. Biex mort mid-dar għall-baħar soqt lilha. Kemm ħriġtha mill-garaxx. — <strong>karozza</strong></td><td>To go from home to the sea I drove it; I only had to take it out of the garage.<br><strong>Biex mort</strong> in order to go / when I went<br><strong>mid-dar</strong> from home<br><strong>għall-baħar</strong> to the sea<br><strong>soqt</strong> I drove<br><strong>lilha</strong> it, feminine, i.e. karozza<br><strong>Kemm</strong> here &quot;only, merely&quot;<br><strong>ħriġtha</strong> I took it out, -ha = it<br><strong>mill-garaxx</strong> from the garage.</td></tr><tr><td>2. Biex sifirt għal Ċipru rkibt lilu. Domna kważi sagħtejn. — <strong>ajruplan</strong></td><td>To travel to Cyprus I took it; it took us almost two hours.<br><strong>Biex sifirt</strong> in order to travel<br><strong>għal Ċipru</strong> to Cyprus<br><strong>rkibt</strong> I rode<br><strong>lilu</strong> it, masculine, i.e. ajruplan<br><strong>Domna</strong> we took (time)<br><strong>kważi</strong> almost<br><strong>sagħtejn</strong> two hours, a dual form.</td></tr><tr><td>3. Biex mort minn Vjenna għall-Islovakkja rkibt lilha. — <strong>ferrovija</strong></td><td>To go from Vienna to Slovakia I took the train.<br><strong>Biex mort</strong> in order to go<br><strong>minn Vjenna</strong> from Vienna<br><strong>għall-Islovakkja</strong> to Slovakia<br><strong>rkibt lilha</strong> I took it, feminine<br><strong>ferrovija</strong> chosen from the options; this does not claim the only real route.</td></tr><tr><td>4. Biex ġarrejt l-affarijiet minn dar għal oħra użajt lilu. — <strong>vann</strong></td><td>To move the things from one home to another I used it.<br><strong>Biex ġarrejt</strong> in order to carry<br><strong>l-affarijiet</strong> the things<br><strong>minn dar għal oħra</strong> from one house to another<br><strong>użajt lilu</strong> I used it, masculine.</td></tr><tr><td>5. Biex mort Għawdex irkibt dan. — <strong>vapur</strong></td><td>To go to Gozo I took this.<br><strong>Biex mort</strong> in order to go<br><strong>Għawdex</strong> Gozo<br><strong>irkibt</strong> I rode<br><strong>dan</strong> this, masculine.</td></tr><tr><td>6. Biex dort Londra rkibt din ħalli ma nikrix karozza. — <strong>tal-linja</strong></td><td>To get round London I took this so as not to hire a car.<br><strong>Biex dort</strong> in order to go round<br><strong>Londra</strong> London<br><strong>rkibt din</strong> I took this, feminine, pointing to karozza tal-linja<br><strong>ħalli</strong> so that<br><strong>ma nikrix</strong> I do not hire<br><strong>karozza</strong> a car.</td></tr><tr><td>7. Biex ma neħilx fit-traffiku nuża dan filgħodu. — <strong>mutur</strong></td><td>So as not to get stuck in traffic I use this in the morning.<br><strong>Biex ma neħilx</strong> so as not to get stuck<br><strong>fit-traffiku</strong> in the traffic<br><strong>nuża</strong> I use<br><strong>dan</strong> this, masculine<br><strong>filgħodu</strong> in the morning.</td></tr><tr><td>8. Filgħodu mort dawra biha u hekk għamilt ukoll attività fiżika. — <strong>rota</strong></td><td>In the morning I went for a ride on it, and that way I also got some exercise.<br><strong>Filgħodu</strong> in the morning<br><strong>mort dawra</strong> I went for a ride<br><strong>biha</strong> with it, feminine<br><strong>u hekk</strong> and that way<br><strong>għamilt ukoll</strong> I also did<br><strong>attività fiżika</strong> physical activity.</td></tr><tr><td>9. Irkibt lilha biex wasslitni eżatt id-dar. Swietni aktar flus minn tal-linja. — <strong>taxi</strong></td><td>I took it so that it would take me right to my door; it cost me more than the bus.<br><strong>Irkibt lilha</strong> I took it, feminine, pointing to the vehicle in this item<br><strong>biex wasslitni</strong> so that it took me, -ni = me<br><strong>eżatt id-dar</strong> right at the door<br><strong>Swietni</strong> it cost me<br><strong>aktar flus</strong> more money<br><strong>minn tal-linja</strong> than the bus.</td></tr></tbody></table><p>Each of the nine options is used once. The gender of <strong>lilu / lilha / dan / din / biha</strong> depends on the vehicle referred back to and on the noun left out, not on the gender of the traveller.</p>',99)])])}const m=r(o,[["render",s]]);export{u as __pageData,m as default};
